/* vuln.c — deliberately vulnerable target */
#include <stdio.h>
#include <string.h>

void win() {
    printf("[*] shell gained\n");
}

void vulnerable(char *input) {
    char buf[64];
    /* strcpy performs no bounds check — classic overflow vector */
    strcpy(buf, input);
    printf("buf: %s\n", buf);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <input>\n", argv[0]);
        return 1;
    }
    vulnerable(argv[1]);
    return 0;
}
